        // update A(0:i,j:j+jb)
        lasyf_gemm<MAX_THDS>(tid, i + 1, jb, kb, minone, A + (i + 1) * lda, lda,
                             W + i + (kw + 1) * ldw, ldw, one, A + j * lda, lda);
        __syncthreads();
    }
}

